// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.AdExperiment.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(adexperiment.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *AdExperimentUpsertBulk) UpdateNewValues() *AdExperimentUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(adexperiment.FieldID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(adexperiment.FieldCreatedAt)
			}
			if _, exists := b.mutation.AccountID(); exists {
				s.SetIgnore(adexperiment.FieldAccountID)
			}
			if _, exists := b.mutation.CampaignID(); exists {
				s.SetIgnore(adexperiment.FieldCampaignID)
			}
			if _, exists := b.mutation.Variable(); exists {
				s.SetIgnore(adexperiment.FieldVariable)
			}
			if _, exists := b.mutation.Metric(); exists {
				s.SetIgnore(adexperiment.FieldMetric)
			}
			if _, exists := b.mutation.Arms(); exists {
				s.SetIgnore(adexperiment.FieldArms)
			}
			if _, exists := b.mutation.StartAt(); exists {
				s.SetIgnore(adexperiment.FieldStartAt)
			}
			if _, exists := b.mutation.CreatedByUserID(); exists {
				s.SetIgnore(adexperiment.FieldCreatedByUserID)
			}
		}
	}))
	return u
}

